import unicodedata

def contar_vogais_consoantes(texto):
    def remover_acentos(s):
        return ''.join(c for c in unicodedata.normalize('NFD', s) if unicodedata.category(c) != 'Mn')
    s = remover_acentos(texto).lower()
    vogais = set('aeiou')
    v = c = 0
    for ch in s:
        if not ch.isalpha():
            continue
        if ch in vogais:
            v += 1
        else:
            c += 1
    return [v, c]
